edits.after:
renderWearableDetailPresentation("WearableManualEntries", "row", {
      noteClass: () => (noteRow ? ' has-note' : ''),
      dateAttribute: () => (escapeHTML(e.date)),
      shortDate: () => (escapeHTML(shortDate(e.date))),
      value: () => (valueRead),
      optionalUnit: () => (unit ? renderWearableDetailPresentation("WearableManualEntries", "unit", {
      unit: () => (escapeHTML(unit))
    }) : ''),
      tags: () => (tagChips),
      accessibleDeleteLabel: () => (escapeHTML(ariaText)),
      deleteActionAttributes: () => (wearableActionAttrs('delete-detail-manual-entry', { metric: metricId, date: e.date })),
      note: () => (noteRow)
    })

renderWearableDetailPresentation("WearableDetailStats", "stat", {
      optionalTooltipAttributes: () => (tooltip ? ` title="${escapeHTML(tooltip)}"` : ''),
      label: () => (escapeHTML(label)),
      value: () => (val),
      optionalSubLabel: () => (sub ? renderWearableDetailPresentation("WearableDetailStats", "subLabel", {
      subLabel: () => (escapeHTML(sub))
    }) : '')
    })

renderWearableDetailPresentation("WearableDetailFeedback", "emptyChartWithManual", {
      emptyWindow: () => (escapeHTML(rangeDef.emptyWindow)),
      olderManualHint: () => (m.primarySource === 'manual' && rangeDef.days != null ? '; switch to All to chart older manual readings' : '')
    })

renderWearableDetailPresentation("WearableDetailChrome", "pairedSourceSwap", {
      systolicActionAttributes: () => (wearableActionAttrs('choose-source', { metric: 'bp_systolic' })),
      systolicSource: () => (escapeHTML(sourceName)),
      diastolicActionAttributes: () => (wearableActionAttrs('choose-source', { metric: 'bp_diastolic' })),
      diastolicSource: () => (escapeHTML(pairedSourceName))
    })

renderWearableDetailPresentation("WearableDetailChrome", "rangePill", {
      activeClass: () => (r.key === rangeKey ? ' active' : ''),
      pressed: () => (r.key === rangeKey),
      rangeActionAttributes: () => (wearableActionAttrs('set-detail-range', { metric: metricId, range: r.key })),
      label: () => (escapeHTML(r.label))
    })
